(()=>{'use strict';const $=id=>document.getElementById(id),base='/api/h3-tools';let selected=null,jobs=[],sending=false,polling=false;const urls=[];let files=[];
function isFL(){return $('h3Method').value==='first_last_frames'}
function maxFiles(){return isFL()?2:9}
function modeUI(){const fl=isFL();$('h3ImagesLabel').textContent=fl?'首尾帧图片（必须2张，按顺序上传）':'参考图片（可选，最多9张）';$('h3MethodNote').textContent=fl?'第1张固定首帧，第2张固定尾帧；一采与二采均接入首尾关键帧。':'参考图用于人物、场景与物体，不固定首尾画面。';$('h3RefsNote').hidden=fl;$('h3ModelNote').textContent=fl?'MiniMax H3 FL2VA · 首尾帧实验 · 一采8步 / 二采4步 · 含原生声音':'Dasiwa MiniMax H3 · 一采8步 / 二采4步 · 含原生声音';}
const labels={preparing:'准备中',queued:'排队中',running:'生成中',first_ready:'一采完成，可以预览后继续二采',completed:'二采完成',failed:'生成失败',cancelled:'已停止'};
async function api(url,body){const r=await fetch(url,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const v=await r.json();if(!r.ok)throw Error(v.error||'请求失败');return v}
let estimateKey='',estimateTimer,estimateVersion=0;
function rangeLabel(range){return range.map(elapsedLabel).join('–');}
function remainingLabel(j){if(j.stage!=='first'||!['queued','running'].includes(j.status))return '';const e=j.first_estimate;if(!e)return '预计剩余：估算中';if(e.overdue)return '已超出历史估算，仍在处理中';return (j.status==='queued'?'生成预计约 ':'预计剩余约 ')+rangeLabel(e.remaining_range_seconds)+'（含处理保存）';}
function estimateForm(){let box=$('firstEstimateText');if(!box){box=document.createElement('p');box.id='firstEstimateText';box.className='subtle';$('size').after(box)}const query=new URLSearchParams({megapixels:$('mp').value,ratio:$('ratio').value,duration:$('duration').value,port:$('port').value,references:String(files.length),video_method:$('h3Method').value}).toString(),key=query+'|'+jobs.filter(x=>x.first_seconds).length;if(key===estimateKey)return;estimateKey=key;box.textContent='一采预计用时：估算中…';clearTimeout(estimateTimer);const version=++estimateVersion;estimateTimer=setTimeout(async()=>{try{const e=await api(base+'/estimate?'+query);if(version!==estimateVersion)return;box.textContent=e?'一采预计用时约 '+rangeLabel(e.total_range_seconds)+'（参考 '+e.sample_count+' 条历史记录，含处理保存）':'一采预计用时：历史数据不足，完成首条后自动估算';}catch{if(version===estimateVersion)box.textContent='一采预计用时：暂无法估算';}},200);}
function alignedSize(v){const n=v/32,f=Math.floor(n);return (n-f===0.5?(f%2===0?f:f+1):Math.round(n))*32}
function dims(){const mp=Number($('mp').value),r=$('ratio').value;let [w,h]=({0.2:[608,352],0.3:[736,416],0.5:[960,544]})[mp];if(r==='9:16')[w,h]=[h,w];if(r==='1:1')w=h=Math.round(Math.sqrt(mp*1e6)/32)*32;return [w,h]}
function sizes(){const [w,h]=dims(),frames=5+17*Math.ceil(Math.max(0,Math.round(Number($('duration').value)*24)-5)/17);$('size').textContent=`一采 ${w} × ${h} · 24帧/秒 · 实际约 ${(frames/24).toFixed(2)} 秒`;const j=selected||{width:w,height:h},s=Number($('scale').value);$('secondSize').textContent=`二采约 ${alignedSize(j.width*s)} × ${alignedSize(j.height*s)}（按32对齐）`;estimateForm()}
function persist(){try{localStorage.setItem('h3-tools-form',JSON.stringify({video_method:$('h3Method').value,prompt:$('prompt').value,megapixels:$('mp').value,ratio:$('ratio').value,duration:$('duration').value,port:$('port').value,selected:selected?.id}))}catch{}}
function video(id,url){const e=$(id);if(url&&e.getAttribute('src')!==url)e.src=url;if(!url){e.pause();e.removeAttribute('src');e.load()}$(id+'Result').hidden=!url;if(url){$(id+'Download').href=url;$(id+'Download').download=`H3-${id}-${selected.id}.mp4`;let links=$(id+'WorkflowLinks');if(!links){links=document.createElement('div');links.id=id+'WorkflowLinks';links.className='tool-links';$(id+'Result').append(links)}const route='/api/open-workflow/'+selected.id+'?kind=h3-'+id+'&port='+selected.port;if(links.dataset.route!==route){links.dataset.route=route;links.replaceChildren();const open=document.createElement('a'),download=document.createElement('a');open.textContent='打开 ComfyUI 工作流 ↗';open.href=route;open.target='_blank';open.rel='noopener';download.textContent='下载工作流';download.href=route+'&download=1';download.download=`H3-${id}-${selected.id}.json`;links.append(open,download)}}}
function currentWorkflowLinks(j){let box=$('currentWorkflowLinks');if(!box){box=document.createElement('div');box.id='currentWorkflowLinks';box.className='tool-links';$('status').after(box)}box.hidden=!j?.prompt_id;if(!j?.prompt_id)return;const stage=j.stage==='second'?'second':'first',route='/api/open-workflow/'+j.id+'?kind=h3-'+stage+'&port='+j.port;if(box.dataset.route===route)return;box.dataset.route=route;box.replaceChildren();const open=document.createElement('a'),download=document.createElement('a');open.href=route;open.target='_blank';open.rel='noopener';open.textContent='打开'+(stage==='first'?'一采':'二采')+' ComfyUI 工作流 ↗';download.href=route+'&download=1';download.textContent='下载'+(stage==='first'?'一采':'二采')+'工作流';box.append(open,download)}
function elapsedLabel(seconds){if(!Number.isFinite(seconds))return '';const n=Math.max(0,Math.round(seconds)),h=Math.floor(n/3600),m=Math.floor(n%3600/60),r=n%60;return(h?h+'小时':'')+(m?m+'分':'')+(r||(!h&&!m)?r+'秒':'');}
let h3Projects=[],h3ProjectsLoaded=false,currentProject=new URLSearchParams(location.search).get('h3project')||localStorage.getItem('h3-tools-current-project')||'legacy-h3';
const projectBox=document.createElement('section');projectBox.setAttribute('aria-label','H3小工具项目');projectBox.style.cssText='margin-bottom:20px;padding:14px;border:1px solid #354556;border-radius:10px';projectBox.innerHTML='<label>当前项目<select id="h3Project" aria-label="H3当前项目"></select></label><div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap"><input id="h3ProjectName" aria-label="H3项目名称" placeholder="输入项目名称" maxlength="80" style="flex:1;min-width:140px"><button id="h3ProjectCreate" type="button">新建项目</button><button id="h3ProjectRename" type="button">重命名</button></div><p id="h3ProjectNote" class="subtle" role="status"></p>';$('form').before(projectBox);
function projectOf(j){return j.tool_project_id||'legacy-h3'}
function drawH3Projects(){const select=$('h3Project');select.replaceChildren();for(const p of h3Projects){const o=document.createElement('option');o.value=p.id;o.textContent=p.name+' · '+jobs.filter(j=>projectOf(j)===p.id).length+'条履历';select.append(o)}select.value=currentProject;$('h3ProjectCreate').disabled=$('h3ProjectRename').disabled=!h3ProjectsLoaded;$('h3ProjectNote').textContent=h3ProjectsLoaded?'当前项目：'+(h3Projects.find(p=>p.id===currentProject)?.name||'原有记录')+'。每次生成新增履历。':'正在读取项目…';}
function switchH3Project(id){currentProject=id;localStorage.setItem('h3-tools-current-project',id);selected=jobs.find(j=>projectOf(j)===id)||null;if(selected)select(selected);else{$('prompt').value='';files=[];renderRefs();render()}persist();}
$('h3Project').onchange=e=>switchH3Project(e.target.value);
$('h3ProjectCreate').onclick=async()=>{try{const p=await api(base+'/projects',{name:$('h3ProjectName').value});h3Projects.push(p);$('h3ProjectName').value='';switchH3Project(p.id)}catch(e){$('h3ProjectNote').textContent=e.message}};
$('h3ProjectRename').onclick=async()=>{try{const p=await api(base+'/projects/'+currentProject,{name:$('h3ProjectName').value});h3Projects=h3Projects.map(x=>x.id===p.id?p:x);$('h3ProjectName').value='';drawH3Projects()}catch(e){$('h3ProjectNote').textContent=e.message}};
api(base+'/projects').then(p=>{h3Projects=p;h3ProjectsLoaded=true;if(!p.some(x=>x.id===currentProject))currentProject='legacy-h3';drawH3Projects()}).catch(e=>$('h3ProjectNote').textContent=e.message);
const moveDialog=document.createElement('dialog');moveDialog.style.cssText='width:min(500px,92vw);background:#172334;color:inherit;border:1px solid #40556b;border-radius:14px;padding:22px';moveDialog.innerHTML='<h3>移动这条履历</h3><label>目标项目<select id="h3MoveTarget"></select></label><p id="h3MoveMessage" role="status"></p><div style="display:flex;gap:10px"><button type="button" id="h3MoveSave">移到项目</button><button type="button" id="h3MoveCancel">取消</button></div>';document.body.append(moveDialog);let movingH3=null;
function openH3Move(j){movingH3=j;const select=$('h3MoveTarget');select.replaceChildren();for(const p of h3Projects.filter(p=>p.id!==projectOf(j))){const o=document.createElement('option');o.value=p.id;o.textContent=p.name;select.append(o)}$('h3MoveSave').disabled=!select.options.length;$('h3MoveMessage').textContent=select.options.length?'只移动这条履历，其余记录不变。':'请先新建另一个H3项目。';moveDialog.showModal()}
$('h3MoveCancel').onclick=()=>moveDialog.close();$('h3MoveSave').onclick=async()=>{const button=$('h3MoveSave');button.disabled=true;try{await api(base+'/'+movingH3.id+'/move',{target_project_id:$('h3MoveTarget').value});if(selected?.id===movingH3.id)selected=null;await refresh();selected=jobs.find(j=>projectOf(j)===currentProject)||null;render();moveDialog.close()}catch(e){$('h3MoveMessage').textContent=e.message}finally{button.disabled=false}};
async function deleteH3History(j){if(!confirm('删除这条履历？视频文件会保留。'))return;try{await api(base+'/'+j.id+'/delete',{});if(selected?.id===j.id)selected=null;await refresh();selected=jobs.find(j=>projectOf(j)===currentProject)||null;render()}catch(e){$('error').textContent=e.message}}
function h3DeviceLabel(j){const entries=Object.entries(j.execution_devices||{});if(entries.length)return entries.map(([stage,d])=>(stage==='first'?'一采GPU：':'二采GPU：')+d.name+(d.vram_total_bytes?' / '+(d.vram_total_bytes/1073741824).toFixed(1)+'GB':'')).join(' · ');const d=j.execution_device;return d?'GPU：'+d.name:'GPU：未记录';}

function jobTiming(j){const parts=[];if(Number.isFinite(j.first_seconds))parts.push('一采用时 '+elapsedLabel(j.first_seconds));if(Number.isFinite(j.second_seconds))parts.push('二采用时 '+elapsedLabel(j.second_seconds));if(['queued','running'].includes(j.status)&&Number.isFinite(j.elapsed_seconds))parts.push((j.stage==='second'?'二采':'一采')+'已用 '+elapsedLabel(j.elapsed_seconds));if(remainingLabel(j))parts.push(remainingLabel(j));return parts.join(' · ');}
function render(){drawH3Projects();const j=selected,running=j&&['preparing','queued','running'].includes(j.status),other=jobs.some(x=>['queued','running','preparing'].includes(x.status));$('generate').disabled=sending||other;$('busy').hidden=!running;$('cancel').disabled=sending;$('secondButton').disabled=sending||other;$('secondControls').hidden=!j?.first_url;video('first',j?.first_url);video('second',j?.second_url);if(j){let text=(j.stage==='second'?'二采 · ':'一采 · ')+(labels[j.status]||j.status);if(running&&j.stage_started_at)text+=` · 已用时 ${Math.floor((j.elapsed_seconds||0)/60)}分${(j.elapsed_seconds||0)%60}秒`;if(running&&remainingLabel(j))text+=' · '+remainingLabel(j);if(!running&&jobTiming(j))text+=' · '+jobTiming(j);text+='\n'+h3DeviceLabel(j);if(j.error)text+='\n'+j.error;$('status').textContent=text;if(j.experiment==='native_h3_two_pass'){$('h3ModelNote').textContent='Pika H3 Flex · 一采6步 / 二采3步 · 保留一采声音';$('secondButton').disabled=true;}}currentWorkflowLinks(j);const history=$('history');history.replaceChildren();for(const x of jobs.filter(x=>projectOf(x)===currentProject)){const b=document.createElement('button');b.type='button';b.classList.toggle('selected',x.id===j?.id);b.textContent=`${new Date(x.created_at).toLocaleString()} · ${labels[x.status]||x.status}${jobTiming(x)?' · '+jobTiming(x):''}\n${x.video_method==='first_last_frames'?'首尾帧':'多图参考'} · ${x.width}×${x.height} · 视频 ${x.actual_duration.toFixed(2)}秒 · ${x.prompt.slice(0,48)}\n${h3DeviceLabel(x)}`;b.onclick=()=>select(x);const row=document.createElement('div');row.style.cssText='display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px';const actions=document.createElement('div');actions.style.cssText='display:flex;flex-direction:column;gap:6px';const move=document.createElement('button'),remove=document.createElement('button');move.type=remove.type='button';move.textContent='移到项目';remove.textContent='删除';remove.style.color='#e8bcb9';move.disabled=remove.disabled=['preparing','queued','running'].includes(x.status);move.onclick=()=>openH3Move(x);remove.onclick=()=>deleteH3History(x);actions.append(move,remove);row.append(b,actions);history.append(row)}sizes()}
function select(j){selected=j;$('h3Method').value=j.video_method||'reference_images';modeUI();$('scale').value=String(j.scale);$('chunk').value=String(j.chunk);$('prompt').value=j.prompt;$('mp').value=String(j.megapixels);$('ratio').value=j.ratio;$('duration').value=j.duration;$('port').value=j.port;persist();render();restoreRefs(j)}
async function restoreRefs(j){try{const restored=[];for(const id of j.upload_ids||[]){const r=await fetch('/api/tools/uploads/'+id);if(!r.ok)throw Error('参考图读取失败');const b=await r.blob();restored.push(new File([b],'参考图-'+(restored.length+1)+'.'+(b.type.split('/')[1]||'png'),{type:b.type}))}if(selected?.id!==j.id)return;files=restored;renderRefs()}catch(e){$('error').textContent=e.message}}
function accept(j){const i=jobs.findIndex(x=>x.id===j.id);if(i<0)jobs.unshift(j);else jobs[i]=j;selected=j;persist();render()}
async function refresh(){if(polling||sending)return;polling=true;try{jobs=await api(base);for(const j of jobs.filter(x=>['queued','running'].includes(x.status))){try{const updated=await api(base+'/'+j.id);jobs[jobs.findIndex(x=>x.id===j.id)]=updated}catch{}}if(selected)selected=jobs.find(x=>x.id===selected.id)||selected;render()}catch(e){$('error').textContent=e.message}finally{polling=false}}
function dataURL(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
function renderRefs(){urls.splice(0).forEach(URL.revokeObjectURL);$('refs').replaceChildren();files.forEach((file,index)=>{const figure=document.createElement('figure'),img=document.createElement('img'),caption=document.createElement('figcaption'),remove=document.createElement('button'),replace=document.createElement('button');const u=URL.createObjectURL(file);urls.push(u);img.src=u;img.alt=file.name;caption.textContent=`${isFL()?(index===0?'首帧':'尾帧'):'<Picture '+(index+1)+'>'} · ${file.name}`;remove.type=replace.type='button';remove.textContent='移除';replace.textContent='更换';remove.onclick=()=>{files.splice(index,1);renderRefs()};replace.onclick=()=>projectPicker(index);figure.append(img,caption,remove,replace);$('refs').append(figure)});const add=document.createElement('button');add.type='button';add.className='h3-add-project';add.textContent='＋\n从项目选图';add.onclick=()=>projectPicker();if(files.length<maxFiles())$('refs').append(add);estimateForm()}
function addFile(file,index=null){if(index===null&&files.length>=maxFiles())throw Error('此模式最多'+maxFiles()+'张图片，请先移除一张');if(file.size>10*1024*1024)throw Error('每张参考图需小于10MB');if(index===null)files.push(file);else files[index]=file;renderRefs()}
function projectPicker(index=null){document.dispatchEvent(new CustomEvent('h3-project-picker',{detail:{index,file:index===null?null:files[index],receive:(file,i)=>addFile(file,i)}}))}
$('images').onchange=()=>{try{const incoming=[...$('images').files];if(files.length+incoming.length>maxFiles())throw Error('此模式最多'+maxFiles()+'张图片');for(const f of incoming)addFile(f);$('error').textContent=''}catch(e){$('error').textContent=e.message}finally{$('images').value=''}};
$('form').onsubmit=async e=>{e.preventDefault();if(sending)return;sending=true;$('error').textContent='';render();try{if(isFL()&&files.length!==2)throw Error('请按顺序提供首帧、尾帧两张图片');if(files.length>maxFiles())throw Error('当前图片数量超出模式上限，请手动移除多余图片');const ids=[];for(const f of files){if(f.size>10*1024*1024)throw Error('每张参考图需小于10MB');ids.push((await api('/api/tools/upload',{image:await dataURL(f)})).id)}accept(await api(base,{tool_project_id:currentProject,video_method:$('h3Method').value,prompt:$('prompt').value,megapixels:Number($('mp').value),ratio:$('ratio').value,duration:Number($('duration').value),port:Number($('port').value),scale:Number($('scale').value),chunk:Number($('chunk').value),upload_ids:ids}))}catch(e){$('error').textContent=e.message}finally{sending=false;render()}};
$('secondButton').onclick=async()=>{if(sending||!selected)return;sending=true;$('error').textContent='';render();try{accept(await api(base+'/'+selected.id+'/second',{scale:Number($('scale').value),chunk:Number($('chunk').value)}))}catch(e){$('error').textContent=e.message}finally{sending=false;render()}};
$('cancel').onclick=async()=>{if(sending||!selected)return;sending=true;render();try{accept(await api(base+'/'+selected.id+'/cancel',{}))}catch(e){$('error').textContent=e.message}finally{sending=false;render()}};
$('h3Method').onchange=()=>{modeUI();renderRefs();persist()};
for(const id of ['mp','ratio','duration','port','prompt','scale','chunk'])$(id).addEventListener('input',()=>{sizes();persist()});
try{const s=JSON.parse(localStorage.getItem('h3-tools-form')||'{}');for(const [id,key] of [['h3Method','video_method'],['prompt','prompt'],['mp','megapixels'],['ratio','ratio'],['duration','duration'],['port','port']])if(s[key]!==undefined)$(id).value=s[key];if(s.selected)selected={id:s.selected}}catch{}
modeUI();
api(base).then(x=>{jobs=x;selected=jobs.find(j=>j.id===selected?.id&&projectOf(j)===currentProject)||jobs.find(j=>projectOf(j)===currentProject)||null;if(selected)select(selected);else render()}).catch(e=>$('error').textContent=e.message);sizes();renderRefs();setInterval(refresh,4000);
const panel=$('h3Panel'),tab=$('h3Tab'),original=document.querySelector('.tool-layout:not(#h3Panel)');
function chooseH3(on){panel.hidden=!on;original.hidden=on;tab.setAttribute('aria-selected',String(on));tab.classList.toggle('primary',on);if(on)for(const b of document.querySelectorAll('[data-kind]'))b.setAttribute('aria-selected','false');sessionStorage.setItem('h3-tools-active',String(on))}
tab.onclick=()=>chooseH3(true);for(const b of document.querySelectorAll('[data-kind]'))b.addEventListener('click',()=>chooseH3(false));
if(new URLSearchParams(location.search).get('tool')==='h3'||sessionStorage.getItem('h3-tools-active')==='true')chooseH3(true);
})();

